def transform(grid):
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(len(row) - 2):
            if row[c] != bg and row[c + 2] == row[c]:
                out[r][c + 1] = 2
    return out
